#requires -Version 7.0
# rm.ps1 - one snapshot of the queue runners (-Watch to refresh, -Json for the object)
#
# Generated by the harness task-flow scaffold and then owned by the project. It forwards through
# tools/harness.ps1, so it never goes stale when the plugin updates. It reads no profile and makes no
# coordination call of its own. An argument you pass wins over the fixed one of the same name:
#     pwsh -NoProfile -File ./rm.ps1 -DryRun
# Exit code: the forwarded script's own.

$fixed     = [ordered]@{  }
$forwarder = Join-Path $PSScriptRoot 'tools/harness.ps1'
$given     = @($args | Where-Object { $_ -match '^-[A-Za-z]' } | ForEach-Object { ($_ -replace '^-', '' -replace ':.*$', '') })
$call      = @('-NoProfile', '-File', $forwarder, 'batch/monitor-spec-queue')
foreach ($k in $fixed.Keys) {
    # A name the caller gave, or a prefix PowerShell would bind to it, replaces the fixed value.
    if (@($given | Where-Object { $k.StartsWith($_, [StringComparison]::OrdinalIgnoreCase) }).Count -gt 0) { continue }
    $call += "-$k"
    if ($fixed[$k] -isnot [bool]) { $call += [string]$fixed[$k] }
}
& pwsh @call @args
exit $LASTEXITCODE
